// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }
    function testFuzz_property(uint256 amount, uint256 depositAmount) public {
        vm.assume(amount > 0);
        vm.assume(depositAmount >= amount);
        address caller = address(0x1234);
        vm.deal(caller, depositAmount);
        vm.startPrank(caller);
        c.deposit{value: depositAmount}();
        uint256 balanceBefore = caller.balance;
        c.withdraw(amount);
        uint256 balanceAfter = caller.balance;
        vm.stopPrank();
        assertTrue(balanceAfter - balanceBefore == amount);
    }
}
